"""Remember normal-window monitor placement; no extra package required."""
import ctypes
import os
from ctypes import wintypes as wt


def _api():
    if os.name != "nt":
        raise OSError("Windows placement unavailable")
    api = ctypes.WinDLL("user32", use_last_error=True)
    api.GetAncestor.argtypes = [wt.HWND, wt.UINT]
    api.GetAncestor.restype = wt.HWND
    api.GetWindowRect.argtypes = [wt.HWND, ctypes.POINTER(wt.RECT)]
    api.GetWindowRect.restype = wt.BOOL
    api.SetWindowPos.argtypes = [wt.HWND, wt.HWND, ctypes.c_int,
                                ctypes.c_int, ctypes.c_int, ctypes.c_int, wt.UINT]
    api.SetWindowPos.restype = wt.BOOL
    return api


def monitors():
    class MonitorInfo(ctypes.Structure):
        _fields_ = [("size", wt.DWORD), ("monitor", wt.RECT),
                    ("work", wt.RECT), ("flags", wt.DWORD),
                    ("device", wt.WCHAR * 32)]

    api = _api()
    callback_type = ctypes.WINFUNCTYPE(
        wt.BOOL, wt.HANDLE, wt.HDC, ctypes.POINTER(wt.RECT), wt.LPARAM)
    api.GetMonitorInfoW.argtypes = [wt.HANDLE, ctypes.POINTER(MonitorInfo)]
    api.GetMonitorInfoW.restype = wt.BOOL
    api.EnumDisplayMonitors.argtypes = [wt.HDC, ctypes.POINTER(wt.RECT),
                                      callback_type, wt.LPARAM]
    api.EnumDisplayMonitors.restype = wt.BOOL
    result = []

    @callback_type
    def collect(handle, dc, rect, data):
        info = MonitorInfo()
        info.size = ctypes.sizeof(info)
        if api.GetMonitorInfoW(handle, ctypes.byref(info)):
            work = info.work
            result.append({"monitor": info.device,
                           "work": (work.left, work.top, work.right, work.bottom),
                           "primary": bool(info.flags & 1)})
        return True

    if not api.EnumDisplayMonitors(None, None, collect, 0) or not result:
        raise OSError("Monitor information unavailable")
    return result


def valid_placement(value):
    return (isinstance(value, dict)
            and set(value) == {"monitor", "x", "y"}
            and isinstance(value["monitor"], str)
            and 0 < len(value["monitor"]) <= 128
            and all(type(value[k]) is int and abs(value[k]) <= 100000
                    for k in ("x", "y")))


def placement_for(rect, screens):
    left, top, right, bottom = rect

    def overlap(screen):
        x1, y1, x2, y2 = screen["work"]
        return max(0, min(right, x2) - max(left, x1)) * max(
            0, min(bottom, y2) - max(top, y1))

    screen = max(screens, key=overlap)
    x1, y1, _, _ = screen["work"]
    return {"monitor": screen["monitor"], "x": left - x1, "y": top - y1}


def target_rect(saved, screens, width, height):
    primary = next((s for s in screens if s["primary"]), screens[0])
    screen = next((s for s in screens if s["monitor"] == saved["monitor"]), None)
    missing = screen is None
    screen = screen or primary
    left, top, right, bottom = screen["work"]
    width = max(1, min(width, right - left))
    height = max(1, min(height, bottom - top))
    x = left + ((right - left - width) // 2 if missing else saved["x"])
    y = top + ((bottom - top - height) // 2 if missing else saved["y"])
    return (max(left, min(x, right - width)),
            max(top, min(y, bottom - height)), width, height)


def _window_rect(root):
    api = _api()
    handle = api.GetAncestor(root.winfo_id(), 2)
    rect = wt.RECT()
    if not handle or not api.GetWindowRect(handle, ctypes.byref(rect)):
        raise OSError("Window information unavailable")
    return api, handle, (rect.left, rect.top, rect.right, rect.bottom)


def capture_placement(root):
    """Keep the last normal position when minimized or maximized."""
    try:
        if root.state() == "normal":
            _, _, rect = _window_rect(root)
            root._ahc_placement = placement_for(rect, monitors())
    except (OSError, AttributeError, RuntimeError):
        pass
    return getattr(root, "_ahc_placement", None)


def restore_placement(root, saved):
    """Call once after constructing the main window; keep centering on failure."""
    def restore():
        try:
            if valid_placement(saved):
                api, handle, rect = _window_rect(root)
                x, y, width, height = target_rect(
                    saved, monitors(), rect[2] - rect[0], rect[3] - rect[1])
                # Absolute Win32 coordinates also support monitors left of primary.
                if not api.SetWindowPos(handle, None, x, y, width, height, 0x14):
                    raise OSError("Window positioning unavailable")
        except (OSError, AttributeError, RuntimeError):
            pass
        capture_placement(root)

        def moved(event):
            if event.widget is root:
                capture_placement(root)

        root.bind("<Configure>", moved, add="+")

    root.after_idle(restore)
